// Get CSV text from earlier node
const sheetItem = $('Fetch Google Sheet CSV').first();
const csvText = sheetItem.json.data || sheetItem.json.body || '';
const lines = csvText.trim().split('\n');

const sheetPeople = [];
for (let i = 1; i < lines.length; i++) {
  // Handle CSV with possible commas in values
  const values = lines[i].split(',').map(v => v.trim());
  if (!values[1]) continue;
  sheetPeople.push({
    name: values[1],
    title: values[2],
    team: values[3],
    email: values[4]
  });
}

// Get current org chart people from the previous node
const orgItem = $('Fetch Current Org Chart').first();
let orgPeople = [];
if (Array.isArray(orgItem.json)) {
  orgPeople = orgItem.json;
} else if (orgItem.json.body && Array.isArray(orgItem.json.body)) {
  orgPeople = orgItem.json.body;
} else if (Array.isArray(orgItem.json.data)) {
  orgPeople = orgItem.json.data;
} else {
  // Try to use the raw json as the array
  orgPeople = Object.values(orgItem.json).find(v => Array.isArray(v)) || [];
}

const orgActive = orgPeople.filter(p => p.isActive !== false && p.isActive !== 0);
const orgNames = new Set(orgActive.map(p => p.name.toLowerCase()));
const sheetNames = new Set(sheetPeople.map(p => p.name.toLowerCase()));

// Find differences
const newHires = sheetPeople.filter(p => !orgNames.has(p.name.toLowerCase()));
const departures = orgActive.filter(p => !sheetNames.has(p.name.toLowerCase()) && p.name !== 'Robbie Galoso');

const titleChanges = [];
for (const sp of sheetPeople) {
  const match = orgActive.find(op => op.name.toLowerCase() === sp.name.toLowerCase());
  if (match && match.title !== sp.title) {
    titleChanges.push({
      name: sp.name,
      oldTitle: match.title,
      newTitle: sp.title
    });
  }
}

const totalChanges = newHires.length + departures.length + titleChanges.length;

let summary = `Org Chart Sync Report - ${new Date().toLocaleDateString()}\n`;
summary += `=======================================\n\n`;

if (totalChanges === 0) {
  summary += 'No changes detected. Org chart is up to date.';
} else {
  summary += `${totalChanges} change(s) detected:\n\n`;

  if (newHires.length > 0) {
    summary += `NEW HIRES (${newHires.length}):\n`;
    newHires.forEach(p => summary += `  + ${p.name} - ${p.title} (${p.team})\n`);
    summary += '\n';
  }

  if (departures.length > 0) {
    summary += `DEPARTURES (${departures.length}):\n`;
    departures.forEach(p => {
      const dept = p.departmentName || p.department || '?';
      summary += `  - ${p.name} - ${p.title} (${dept})\n`;
    });
    summary += '\n';
  }

  if (titleChanges.length > 0) {
    summary += `TITLE/ROLE CHANGES (${titleChanges.length}):\n`;
    titleChanges.forEach(c => summary += `  ~ ${c.name}: "${c.oldTitle}" -> "${c.newTitle}"\n`);
    summary += '\n';
  }
}

return {
  json: {
    totalChanges,
    summary,
    newHiresCount: newHires.length,
    departuresCount: departures.length,
    titleChangesCount: titleChanges.length,
    sheetPeopleCount: sheetPeople.length,
    orgPeopleActiveCount: orgActive.length
  }
};
